import{z as i,x as B,o as s,c as d,q as r,j as l,D as n,d as E,s as A,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"密钥管理与 HSM","description":"","frontmatter":{"title":"密钥管理与 HSM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/key-management-hsm.md","filePath":"cs/key-management-hsm.md","lastUpdated":1791063341000}'),p={name:"cs/key-management-hsm.md"};function m(S,a,h,D,C,c){const t=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="密钥管理与-hsm" tabindex="-1">密钥管理与 HSM <a class="header-anchor" href="#密钥管理与-hsm" aria-label="Permalink to &quot;密钥管理与 HSM&quot;">​</a></h1><div class="epigraph"><p>算法正确只覆盖「运算」；密钥的生成、存放、使用、轮换、销毁才覆盖生命周期。HSM 把私钥关进盒子，让「算而不出」成为策略，而不是再加长 AES。</p><footer>—— 据 NIST SP 800-57；Anderson 对密钥生命周期；对照 PKCS #11 的角色分工</footer></div><p>上一课<a href="/cs/hkdf">HKDF</a>会派生多把键。缺口是<strong>这些比特住在哪</strong>。原语课序在 HKDF 结束；本课序从生命周期起。不重写 PRF 定义。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件密钥在进程内存、交换分区、日志、快照里复制。威胁模型若含内存读取，AEAD 帮不上。HSM/TEE 提供：键不导出、使用要授权、审计。缺口是管理平面，不是又一种分组密码。</p><h3 id="hsm-不是魔法" tabindex="-1">HSM 不是魔法 <a class="header-anchor" href="#hsm-不是魔法" aria-label="Permalink to &quot;HSM 不是魔法&quot;">​</a></h3><p>盒子固件、管理卡、备份密钥、提权路径仍是 TCB。Anderson：多数事故是流程，不是因式分解。</p><p><span class="marginnote">SP 800-57 分密钥类型与周期。PKCS #11 是常见 API 形状。后课 seL4 从微内核验证谈 TCB；本课只把 HSM 当密钥的引用监视器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出状态机：生成/注入、激活、轮换、吊销、销毁。对照软件 KMS 与硬件。签名与解密在盒内完成，主机只见明文业务数据或密文。备份用拆分或封装钥。</p>',11)),(s(),l(o,null,{default:n(()=>[A(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%22%5D%20--%3E%20USE%5B%22%E7%9B%92%E5%86%85%E4%BD%BF%E7%94%A8%22%5D%0A%20%20USE%20--%3E%20ROT%5B%22%E8%BD%AE%E6%8D%A2%22%5D%0A%20%20ROT%20--%3E%20DEST%5B%22%E9%94%80%E6%AF%81%22%5D%0A%20%20USE%20--%3E%20POL%5B%22%E6%8E%88%E6%9D%83%E4%B8%8E%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"最小特权落到键：谁能调用 Sign。前向保密下一课问会话键是否短命——HSM 管长期根，不自动让会话遗忘。二者要一起设计。",-1)),a[5]||(a[5]=e("p",null,[E("第一张图讲键的一生；这张回答具体问题："),e("strong",null,"「算而不出」在机器层面是什么样"),E("——主机递进去的从来不是密钥请求，而是待处理的数据。")],-1)),(s(),l(o,null,{default:n(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E4%B8%BB%E6%9C%BA%E5%BA%94%E7%94%A8%22%5D%20--%3E%7C%22%E9%80%81%E5%85%A5%E5%BE%85%E7%AD%BE%E5%93%88%E5%B8%8C%22%7C%20HSM%5B%22HSM%20%E5%86%85%E9%83%A8%22%5D%0A%20%20POL%7B%22%E7%AD%96%E7%95%A5%EF%BC%9A%E8%BF%99%E6%8A%8A%E9%94%AE%EF%BC%9Cbr%EF%BC%9E%E5%85%81%E8%AE%B8%E8%AF%A5%E5%BA%94%E7%94%A8%2F%E6%93%8D%E4%BD%9C%E5%90%97%EF%BC%9F%22%7D%20--%3E%7C%22%E6%8B%92%E7%BB%9D%22%7C%20NO%5B%22%E8%BF%94%E5%9B%9E%E9%94%99%E8%AF%AF%E5%B9%B6%E8%AE%B0%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20POL%20--%3E%7C%22%E5%85%81%E8%AE%B8%22%7C%20SIG%5B%22%E7%9B%92%E5%86%85%E7%94%A8%E7%A7%81%E9%92%A5%E8%BF%90%E7%AE%97%22%5D%0A%20%20SIG%20--%3E%7C%22%E5%8F%AA%E9%80%81%E5%87%BA%E7%AD%BE%E5%90%8D%22%7C%20APP%0A%20%20KEY%5B%22%E7%A7%81%E9%92%A5%22%5D%20--%3E%20SIG%0A%20%20KEY%20--%3E%7C%22%E6%B0%B8%E4%B8%8D%E5%AF%BC%E5%87%BA%22%7C%20BOXOUT%5B%22%E4%BB%85%E9%94%80%E6%AF%81%E6%88%96%E5%A4%87%E4%BB%BD%E5%B0%81%E8%A3%85%EF%BC%8C%E4%B8%8D%E5%87%BA%E7%9B%92%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：HSM 像银行柜台的点钞机——钞票（待签数据）递进去、结果（签名）递出来，而点验的规则和现金的存放都在柜台内部；你能决定「办不办这笔业务」，却永远摸不到保险库本身。</span></p><p><span class="marginnote">数字实例：常见实践里，直接加密业务数据的密钥数月一换，而保护它们的根密钥数年一换、深藏 HSM；层次化的关键好处是轮换下层键时根密钥纹丝不动——换的不是保险库，只是保险库里的一只抽屉。</span></p><p><span class="marginnote">常见误区：初学者容易以为「把 AES 换成更长的密钥」就能补上管理缺漏。密钥泄漏发生在内存、交换分区、日志、快照这些<strong>存放环节</strong>，算法再强也照泄不误；HSM 缩小的正是这个暴露面，而不是数学强度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某厂商的管理口令默认值清单当利用手册。下一课前向保密：长期根泄漏后历史会话是否仍保密。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HKDF 产出键；本课管键的住处与谁能用。</li><li>HSM 让私钥不可导出成为策略。</li><li>生命周期失败比算法过时更常见。</li><li>下一课：前向保密与短命会话键。</li><li>出处：NIST SP 800-57；Anderson, <em>Security Engineering</em>；PKCS #11。</li></ul>',7))])}const f=i(p,[["render",m]]);export{P as __pageData,f as default};
